   mcq('ماذا قالت الدكتورة سارة عن نفسها؟', ['لا تملك سيّارة', 'تملك سيّارة لأنّ المستشفى بعيد ولا حافلة في الليل', 'تمشي إلى المستشفى'], 1, 'مع نورة في الرأي ومع خالد في الواقع، كما قال يوسف: نصف الوقت.'),
