   tap('المس كلمة التسليم', ['صحيح', 'أنّ', 'الفرق', 'كبير،', 'لكنّ', 'الألفين', 'يشتريان', 'الوقت'], 'صحيح'),
   tap('المس كلمة الخاتمة', ['أمشي', 'كثيرًا', 'ولذلك', 'أرى', 'أنّ', 'الحافلة', 'تكفي'], 'ولذلك'),
   tap('المس كلمة الموقف', ['لا', 'أوافق،', 'لأنّ', 'السيّارة', 'تصنع', 'ثلاث', 'مشكلات'], 'أوافق،'),
